import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 下如何修改用户名（同時修改用户組名和家目錄） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下如何修改用户名（同時修改用户組名和家目錄） | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下如何修改用户名（同時修改用户組名和家目錄） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下如何修改用户名（同時修改用户組名和家目錄） | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171128 How to rename user in Linux (also rename group - home directory)","title":"Linux 下如何修改用户名（同時修改用户組名和家目錄）","tag":"201712","desc":""},"relativePath":"201712/20171128 How to rename user in Linux (also rename group - home directory).md","filePath":"[post].md"}'),u={name:"201712/20171128 How to rename user in Linux (also rename group - home directory).md"};function h(g,e,c,k,m,b){const a=o("Link");return d(),r("div",null,[e[13]||(e[13]=p(`<h1 id="linux-下如何修改用户名-同時修改用户組名和家目錄" tabindex="-1">Linux 下如何修改用户名（同時修改用户組名和家目錄） <a class="header-anchor" href="#linux-下如何修改用户名-同時修改用户組名和家目錄" aria-label="Permalink to “Linux 下如何修改用户名（同時修改用户組名和家目錄）”">​</a></h1><p>有時候，由於某些原因，我們可能會需要重命名用户名。我們可以很容易地修改用户名以及對應的家目錄和 UID。</p><p>本教程將會討論這些東西。讓我們先從修改用户名開始。</p><h3 id="修改用户名" tabindex="-1">修改用户名 <a class="header-anchor" href="#修改用户名" aria-label="Permalink to “修改用户名”">​</a></h3><p>我們使用 <code>usermod</code> 來修改用户名。其語法為，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ usermod -l new_username old_username</span></span></code></pre></div><p>舉個例子，假設我們有一個名叫 <code>dan</code> 的用户想要重命名為 <code>susan</code>，那麼在終端下執行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -l susan dan</span></span></code></pre></div><p>這隻會更改用户名，而其他的東西，比如用户組，家目錄，UID 等都保持不變。</p><p><strong>注意：-</strong> 你需要從要改名的帳號中登出並殺掉該用户的所有進程，要殺掉該用户的所有進程可以執行下面命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pkill -u dan</span></span>
<span class="line"><span>$ sudo pkill -9 -u dan</span></span></code></pre></div><h3 id="修改家目錄" tabindex="-1">修改家目錄 <a class="header-anchor" href="#修改家目錄" aria-label="Permalink to “修改家目錄”">​</a></h3><p>要同時更改家目錄，我們需要在執行 <code>usermod</code> 命令的同時加上 <code>-d</code> 選項，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -d /home/susan -m susan</span></span></code></pre></div><h3 id="更改用户-uid" tabindex="-1">更改用户 UID <a class="header-anchor" href="#更改用户-uid" aria-label="Permalink to “更改用户 UID”">​</a></h3><p>執行下面命令修改用户 UID，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -u 2000 susan</span></span></code></pre></div><p>這裏 <code>2000</code> 就是用户的新 UID。</p><h3 id="修改用户組名" tabindex="-1">修改用户組名 <a class="header-anchor" href="#修改用户組名" aria-label="Permalink to “修改用户組名”">​</a></h3><p>要把用户組名從 <code>dan</code> 修改為 <code>susan</code>，我們需要使用 <code>groupmod</code> 命令。使用下面命令來修改用户組名，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groupmod -n susan dan</span></span></code></pre></div><p>做完修改後，可以使用 <code>id</code> 命令來檢查，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id susan</span></span></code></pre></div><p>這篇教導如何修改用户名的指南就此結束了。有任何疑問或建議，歡迎給我們留言。</p><hr>`,25)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"http://linuxtechlab.com/rename-user-in-linux-rename-home-directory/"},{default:t(()=>[...e[0]||(e[0]=[s("http://linuxtechlab.com/rename-user-in-linux-rename-home-directory/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...e[2]||(e[2]=[s("Shusain",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const y=l(u,[["render",h]]);export{C as __pageData,y as default};
